#!/usr/bin/env python3
"""The Cook Islands' electricity and renewable energy generated by island a quarter, 2014 to 2025, as the Cook Islands
Statistics Office (CISO, Ministry of Finance and Economic Management) gives them in its Energy Statistics tables for the
December Quarter 2025, from Te Aponga Uira's and the Outer Islands Admin Office's figures (session 2603, chain 129; the ERW
held the Cook Islands only in EIA's international table).

Energy Research Warehouse (ERW) connector. One series table, warehouse/output/cisos_cook_electricity_quarterly.csv, from one
workbook (no key):

    https://stats.gov.ck/download/508/2025/7743/energy-statistics-tables-december-quarter-2025.xlsx

    entity      cisos:ck:<island>: cook_islands (the total) and the eleven islands of the tables
    variable    generation (Table 1, "Electricity Generated"), renewable_generation (Table 2, "Renewable Energy Generated")
    unit        MWh (the tables' kWh '000); ts_utc the quarter's first day; freq P3M; geo CK
    node        the island as printed, its footnote number removed
    x_status    p (provisional) or r (revised) as the quarter's label marks it, else empty

The two sheets are read by their titles; the header row names the islands, each later row a quarter (the year in the first
column of its first quarter). A cell "-" is the key's "nil or zero" and is written as 0; a cell printed for "not available"
(an ellipsis) or "not applicable" ("..") is not written. The workbook holds some estimated islands' figures with fractions it
displays as whole numbers; the value is the cell's, to 3 decimals. Checks: each quarter's islands add to the Cook Islands within
1 MWh; each island's four quarters add to Tables 3 and 4's year within 1 MWh or 2%, the larger, where both are given (a gap
above 1 MWh is listed in the file's header). Tables 3 and 4 are not
written. Table 1 is not read as including Table 2 (Mitiaro has renewable energy and no "electricity generated" since 2017);
the two are not added. Nothing is filled.

    python warehouse/connectors/cisos_cook_electricity.py [--offline] [--fresh] [--out-dir DIR]

Ceiling: one request a run, saved in warehouse/raw/cisos_ck/ and reused unless --fresh; --offline asks nothing. Each quarter's
tables have their own address; a later quarter needs the address changed. stats.gov.ck's robots file names * and closes only
the site's system paths (session 2603). License: internal. The site reads "Copyright (c) 2023 Cook Islands Statistics Office -
Ministry of Finance and Economic Management"; no terms of reuse found; internal until a ruling.
"""

import argparse
import datetime as dt
import io
import os
import re
import sys
import traceback

import openpyxl
import pandas as pd

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import iso_prices as ip  # noqa: E402

NAME = "cisos_cook_electricity_quarterly"
CONNECTOR = "cisos_ck"
SOURCE = "cisos_ck:energy_statistics_tables_2025q4"
HOST = "stats.gov.ck"
URL = "https://stats.gov.ck/download/508/2025/7743/energy-statistics-tables-december-quarter-2025.xlsx"
UA = {"User-Agent": "Mozilla/5.0 (compatible; ERW-connector/0.1; +https://github.com/SamuelEnrique/erw)"}
CITATION = ("Cook Islands Statistics Office, Energy Statistics: December Quarter 2025, Tables 1 and 2 (source: Te Aponga Uira, "
            "Rarotonga and the Outer Islands Admin Office)")
SHEETS = {"Table 1": ("Electricity Generated", "generation"), "Table 2": ("Renewable Energy Generated", "renewable_generation")}
ANNUAL = {"Electricity Generated": "generation", "Renewable Energy Generated": "renewable_generation"}
QUARTER = {"Mar": "01", "Jun": "04", "Sep": "07", "Dec": "10"}
NIL, NOT_AVAILABLE, NOT_APPLICABLE = "-", chr(0x2026), ".."
X_COLS = ["x_status"]


def slug(s):
    return re.sub(r"[^a-z0-9]+", "_", s.lower()).strip("_")


def island(s):
    return re.sub(r"\s+\d+$", "", str(s).strip())


def cell(v, where):
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return float(v)
    s = str(v).strip() if v is not None else ""
    if s == NIL:
        return 0.0
    if s in (NOT_AVAILABLE, NOT_APPLICABLE):
        return None
    raise RuntimeError(f"{where}: a cell not in the key: {v!r}")


def header(rows, title):
    if not any(r and r[0] is not None and str(r[0]).strip() == title for r in rows[:3]):
        raise RuntimeError(f"the title {title!r} not found")
    hd = [k for k, r in enumerate(rows) if "Cook Islands" in [str(v).strip() if v is not None else None for v in r]]
    if not hd:
        raise RuntimeError(f"{title}: the header row not found")
    return hd


def parse_quarterly(rows, title, variable):
    hd = header(rows, title)
    if len(hd) != 1:
        raise RuntimeError(f"{title}: the header row found {len(hd)} times")
    h = rows[hd[0]]
    cols = [(j, island(v)) for j, v in enumerate(h) if v is not None and str(v).strip()]
    if cols[0][1] != "Cook Islands":
        raise RuntimeError(f"{title}: the first column is {cols[0][1]!r}")
    unit = [str(v) for v in rows[hd[0] + 1] if v is not None]
    if unit != ["Electricity (kwh '000)"]:
        raise RuntimeError(f"{title}: the unit line is {unit!r}")
    out, year, seen = [], None, set()
    for r in rows[hd[0] + 2:]:
        if not any(v is not None for v in r):
            continue
        if r[0] is not None:
            year = int(r[0])
        m = re.fullmatch(r"(Mar|Jun|Sep|Dec)\s*(?:\((p|r)\))?", str(r[1] or "").strip())
        if year is None or not m:
            raise RuntimeError(f"{title}: a row not a quarter: {r!r}")
        ts = f"{year}-{QUARTER[m.group(1)]}-01T00:00:00Z"
        if ts in seen:
            raise RuntimeError(f"{title}: {ts} given twice")
        seen.add(ts)
        vals = {name: cell(r[j], f"{title} {ts} {name}") for j, name in cols}
        if vals["Cook Islands"] is None:
            raise RuntimeError(f"{title} {ts}: no total")
        s = sum(v for name, v in vals.items() if name != "Cook Islands" and v is not None)
        if abs(s - vals["Cook Islands"]) > 1:
            raise RuntimeError(f"{title} {ts}: the islands make {s:.3f}, the Cook Islands {vals['Cook Islands']}")
        for name, v in vals.items():
            if v is not None:
                out.append(dict(entity=f"cisos:ck:{slug(name)}", variable=variable, ts_utc=ts, value=round(v, 3), node=name,
                                x_status=m.group(2) or ""))
    quarters = sorted(seen)
    for a, b in zip(quarters, quarters[1:]):
        ya, ma = int(a[:4]), int(a[5:7])
        if (ya + (ma == 10), 1 if ma == 10 else ma + 3) != (int(b[:4]), int(b[5:7])):
            raise RuntimeError(f"{title}: the quarters jump from {a} to {b}")
    return out


def parse_annual(rows):
    got = {}
    starts = [k for k, r in enumerate(rows) if r and r[0] is not None and str(r[0]).strip() in ("Table 3", "Table 4")]
    if len(starts) != 2:
        raise RuntimeError(f"Tables 3 and 4 found {len(starts)} times")
    for k, end in zip(starts, starts[1:] + [len(rows)]):
        block = rows[k:end]
        title = str(block[1][0]).strip()
        if title not in ANNUAL:
            raise RuntimeError(f"an annual table titled {title!r}")
        hd = [i for i, r in enumerate(block) if r and len(r) > 1 and r[1] is not None and str(r[1]).strip() == "Cook Islands"]
        if len(hd) != 1:
            raise RuntimeError(f"{title} (annual): the header row found {len(hd)} times")
        cols = [(j, island(v)) for j, v in enumerate(block[hd[0]]) if v is not None and str(v).strip()]
        for r in block[hd[0] + 1:]:
            if r[0] is None:
                continue
            for j, name in cols:
                got[(ANNUAL[title], slug(name), int(r[0]))] = cell(r[j], f"{title} {r[0]} {name}")
    return got


def parse(content, base):
    wb = openpyxl.load_workbook(io.BytesIO(content), data_only=True, read_only=True)
    out = []
    for sheet, (title, variable) in SHEETS.items():
        if sheet not in wb.sheetnames:
            raise RuntimeError(f"the sheet {sheet!r} not found: {wb.sheetnames}")
        out += parse_quarterly([tuple(r) for r in wb[sheet].iter_rows(values_only=True)], title, variable)
    annual_sheet = [s for s in wb.sheetnames if s.startswith("Table 3")]
    if len(annual_sheet) != 1:
        raise RuntimeError(f"the annual sheet found {len(annual_sheet)} times")
    annual = parse_annual([tuple(r) for r in wb[annual_sheet[0]].iter_rows(values_only=True)])
    t = pd.DataFrame(out)
    t["year"] = t.ts_utc.str[:4].astype(int)
    t["item"] = t.entity.str.split(":").str[-1]
    checked, gaps = 0, []
    for (variable, item, year), g in t.groupby(["variable", "item", "year"]):
        a = annual.get((variable, item, year))
        if a is None or len(g) != 4:
            continue
        if abs(g.value.sum() - a) > max(1, 0.02 * abs(a)):
            raise RuntimeError(f"{variable} {item} {year}: the quarters make {g.value.sum():.3f}, the year {a}")
        if abs(g.value.sum() - a) > 1:
            gaps.append(f"{variable} {item} {year} quarters {g.value.sum():,.2f}, year {a:,.2f}")
        checked += 1
    if checked < 100:
        raise RuntimeError(f"only {checked} years checked against Tables 3 and 4")
    t = t.drop(columns=["year", "item"])
    for k, v in dict(unit="MWh", freq="P3M", geo="CK", market="", **base).items():
        t[k] = v
    return t, checked, gaps


def main(argv=None):
    ap = argparse.ArgumentParser(description="CISO: the Cook Islands' electricity generated by island a quarter, 2014 to 2025")
    ap.add_argument("--offline", action="store_true", help="the saved workbook only, no request")
    ap.add_argument("--fresh", action="store_true", help="ask for the workbook again")
    ap.add_argument("--out-dir", help="a trial: the table under this folder, not warehouse/output")
    args = ap.parse_args(argv)
    if ip.paused(CONNECTOR) or ip.paused_host(HOST):
        print(f"{NAME}: the publisher is paused (warehouse/metadata/paused_sources.csv); nothing asked")
        return 0
    if args.out_dir:
        raw_dir = ip.RAW_DIR
        ip.set_out_dir(args.out_dir)
        ip.RAW_DIR = raw_dir
    os.makedirs(ip.LOG_DIR, exist_ok=True)
    run_id = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    log = ip.Log(os.path.join(ip.LOG_DIR, f"{CONNECTOR}_{run_id}.log"))
    ip.RAW.open(CONNECTOR, run_id)
    results = []
    try:
        content, rec = ip.fetch_raw(CONNECTOR, URL, log, offline=args.offline, fresh=args.fresh, headers=UA, timeout=180, pause=1)
        # the server sends the response's own time as its last-modified time, not the file's: no vintage
        base = dict(source=SOURCE, source_url=URL, retrieved_at=rec.get("retrieved_at") or "", vintage="")
        t, checked, gaps = parse(content, base)
        cols = ip.SERIES_COLS + X_COLS
        t = t[cols].sort_values(["entity", "variable", "ts_utc"]).reset_index(drop=True)
        tot = t[(t.entity == "cisos:ck:cook_islands") & (t.variable == "generation")]
        head = [
            "Energy Research Warehouse (ERW): Cook Islands Statistics Office, Energy Statistics: December Quarter 2025, Tables 1 and 2: "
            "electricity and renewable energy generated by island a quarter, 2014 to 2025 (session 2603)",
            "Shape: series (docs/datastandard.md v0). entity cisos:ck:<island> (cook_islands the total); variable generation (Table 1) "
            "or renewable_generation (Table 2), not added; unit MWh (the tables' kWh '000); ts_utc the quarter's first day; freq P3M; "
            "geo CK; node the island; x_status p provisional, r revised.",
            f"{len(t)} rows; the Cook Islands' generation {tot.value.iloc[0]:,.0f} MWh in {tot.ts_utc.iloc[0][:7]}, {tot.value.iloc[-1]:,.0f} "
            f"MWh in {tot.ts_utc.iloc[-1][:7]}. '-' (nil or zero) written as 0; not available not written; {checked} island-years checked "
            "against Tables 3 and 4, those differing by more than 1 MWh: " + ("; ".join(gaps) or "none") + ". Nothing is filled.",
            f"Retrieved: {run_id} (UTC) by warehouse/connectors/cisos_cook_electricity.py; the workbook retrieved {base['retrieved_at']}",
            f"Run log: warehouse/output/logs/{CONNECTOR}_{run_id}.log",
            f"Raw files: warehouse/raw/{CONNECTOR}/ (not in git)",
            f"Source: {SOURCE} {CITATION}",
            f"  access: {URL}",
            f"License: internal. The Statistics Office's site states only its copyright line; internal until a ruling. Cite: {CITATION}.",
        ]
        ip.write_snapshot(t, NAME, head, log, cols)
        results.append(dict(table=NAME, market="all", status="ok", detail=f"{len(t)} rows"))
        print(f"{NAME}: {len(t)} rows, {t.entity.nunique()} entities, {checked} island-years checked")
    except Exception:
        tb = ip.redact(traceback.format_exc())
        log(f"{NAME} FAILED, no output file written:\n{tb}")
        print(f"{NAME} FAILED, no output file written: {tb.strip().splitlines()[-1]}", file=sys.stderr)
        results.append(dict(table=NAME, market="all", status="failed", detail=tb.strip().splitlines()[-1][:300]))
    if not args.out_dir:
        if results and results[0]["status"] == "ok":
            ip.update_sources([dict(source=SOURCE, publisher="Cook Islands Statistics Office",
                                    report="Energy Statistics: December Quarter 2025, Tables 1 and 2 (electricity and renewable energy generated)",
                                    report_url=URL, document_list="https://stats.gov.ck/miscellaneous-statistics-december-quarter-2025/",
                                    license="internal", tables=[NAME])])
        ip.write_status(CONNECTOR, run_id, results)
    log.close()
    return 0 if all(r["status"] == "ok" for r in results) else 1


if __name__ == "__main__":
    sys.exit(main())
